import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第二十二章","description":"《正易心法》第二十二章——卦义未审，须求变复：变为一爻之变、复为一体之复；以蒙/师、屯/比（一爻之变）与大有/需晋、升/姤复（一体之复）为证，求得不唯辞合、义实通明。","frontmatter":{"title":"正易心法·第二十二章","description":"《正易心法》第二十二章——卦义未审，须求变复：变为一爻之变、复为一体之复；以蒙/师、屯/比（一爻之变）与大有/需晋、升/姤复（一体之复）为证，求得不唯辞合、义实通明。","category":"guide","aliases":["正易心法第二十二章","卦义未审须求变复","义实通明"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-22.md","filePath":"yijing/zheng-yi-xin-fa/chapter-22.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-22.md"},x=p({...c,setup(u){const i=[{id:"z22-01",label:"一、卦义未审须求变复",showLabel:!0,sentences:[["卦义未",{text:"审",glossary:"shen"},"，须求",{text:"变复",glossary:"bianfu"},"。不唯",{text:"辞合",glossary:"cihe"},"，",{text:"义实通明",glossary:"yishiTongming"},"。"]],note:["卦的义理还没有弄清楚时，必须通过变卦和复卦来推求。不只是文辞上符合，义理要真正贯通明白。（**「不唯辞合，义实通明」是全书的方法论总结句**：「辞合」是表层（文辞上说得通，即第三章批评的「依文解义」）；「义实通明」是深层（义理真正贯通，即第一章说的「知落处」）。**读卦的终点不是会背卦辞，而是真见其所以然。**）"]},{id:"z22-02",label:"二、变为一爻之变",showLabel:!0,sentences:[["变为",{text:"一爻之变",glossary:"yiyaoZhibian"},"，复为",{text:"一体之复",glossary:"yitiZhifu"},"。即复变之辞而观之，自然之义，无不与本卦吻合，以见阴阳之气。"]],note:["变，是一爻发生变化；复，是整个上体或下体复归。就着变卦和复卦的辞来看，自然的义理无不与本卦吻合——由此可以见到阴阳之气的运行。（两者是一对：**「变」向前看（一爻动了会怎样），「复」向后看（这一体从哪里来）**。一个卦的义理不只在它自身的辞中，也在它的变卦和复卦中——**三者共同构成完整的义理网络。**）"]},{id:"z22-03",label:"三、一爻之变之例",showLabel:!0,sentences:[["如蒙上九曰：“击蒙。”变为师，上六则云“小人勿用。”屯初九曰：“以贵下贱，大得民也。”变为比，初六则云“有孚比之，无咎。”此一爻之辞合也。"]],note:["比如蒙卦上九说「击蒙」，变为师卦，师卦上六就说「小人勿用」；屯卦初九说「以贵下贱，大得民也」，变为比卦，比卦初六就说「有孚比之，无咎」——这是一爻之变、辞义相合的例子。（两例都说明：**本爻的「刚」一旦改变，义理随之翻转**。蒙上九的「刚」是能「击蒙」的原因，一旦这个刚消失，就成了「小人勿用」；屯初九的「以贵下贱」，正是比卦「有孚比之」的基础。）"]},{id:"z22-04",label:"四、一体之复之例",showLabel:!0,sentences:[["如大有上体复需，有饮食之",{text:"燕",glossary:"yan"},"；下体复晋，有",{text:"昭明",glossary:"zhaoming"},"之德。"]],note:["比如大有卦，上体复归为需卦，有饮食宴乐之象；下体复归为晋卦，有昭明之德。（**用复卦找到义理的两个来源**：大有＝大丰收，其「饮食宴乐」来自需，其「光明昭著」来自晋——一个说内容，一个说品质。）"]},{id:"z22-05",label:"五、升卦之例",showLabel:!0,sentences:[["升上体复姤，姤一阴升；下体复复，复一阳升。此一体之义合也。"]],note:["升卦的上体复归为姤卦，姤是一阴上升；下体复归为复卦，复是一阳上升——这是一体之复、义理相合的例子。（**升卦的「上升」，阴阳两个方向都有根据**：上体得姤（一阴升），下体得复（一阳升）——不是单向的「升」，而是阴阳同升。这就比单看卦辞「元亨，用见大人」精确得多。）"]},{id:"z22-06",label:"六、自然明矣",showLabel:!0,sentences:[["苟卦义未审，能以此求之，自然明矣。"]],note:["如果卦义还没有弄清楚，能用这个方法来推求，自然就明白了。（**本章是全书最后一个方法论工具**：前二十一章建立了象、数、本体论，本章给出读卦的最后一把钥匙——**变复**。它与第十九章的「一卦具八卦」正好配成一对：第十九章是静态的（内含），本章是动态的（变化）。）"]}],o=[{id:"shen",term:"审",pinyin:"shěn",meaning:"审察，弄清楚。「卦义未审」即卦的义理还没有弄清楚。"},{id:"bianfu",term:"变复",pinyin:"biàn fù",meaning:"变卦与复卦。变＝一爻之变，复＝一体之复。读卦的最后一个工具。"},{id:"cihe",term:"辞合",pinyin:"cí hé",meaning:"文辞上符合。这是表层——只做到辞合，仍是第三章批评的「依文解义」。"},{id:"yishiTongming",term:"义实通明",pinyin:"yì shí tōng míng",meaning:"义理真正贯通明白。实＝真实，非空言；通明＝贯通明白。全书方法论的总结句。"},{id:"yiyaoZhibian",term:"一爻之变",pinyin:"yī yáo zhī biàn",meaning:"某一爻发生变化（阴变阳或阳变阴），得到变卦。"},{id:"yitiZhifu",term:"一体之复",pinyin:"yī tǐ zhī fù",meaning:"整个上体（外卦）或下体（内卦）复归其本宫之卦。"},{id:"yan",term:"燕",pinyin:"yàn",meaning:"通「宴」，宴乐。需卦有「饮食宴乐」之义，此处指大有上体复需所得之象。"},{id:"zhaoming",term:"昭明",pinyin:"zhāo míng",meaning:"光明昭著。晋卦有「昭明」之义（晋为日出地上）。"}];return(b,a)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return d(),g("div",null,[a[0]||(a[0]=t(`<h1 id="正易心法·第二十二章" tabindex="-1">正易心法·第二十二章 <a class="header-anchor" href="#正易心法·第二十二章" aria-label="Permalink to &quot;正易心法·第二十二章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是<strong>全书方法论的最终总结</strong>，给出读卦的最后一个工具：<strong>变复</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前二十一章：基础论（一至八）→ 宇宙生成论（九至十一）→ 方法论（十二至十五）</span></span>
<span class="line"><span>           → 反对体系（十六至十八）→ 读卦技术（十九）→ 哲学归宿（二十至二十一）</span></span>
<span class="line"><span>第二十二章：在哲学归宿之后，给出最后的实践方法——变复</span></span></code></pre></div><p><strong>结构</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标题句（结论）：卦义未审，须求变复，义实通明</span></span>
<span class="line"><span>注解（方法）  ：变＝一爻之变；复＝一体之复</span></span>
<span class="line"><span>注解（例证）  ：蒙变师、屯变比（一爻之变）；大有复需／晋、升复姤／复（一体之复）</span></span>
<span class="line"><span>注解（总结）  ：苟卦义未审，能以此求之，自然明矣</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「变复」能揭示义理，基于一个假设</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阴阳之气是连续流动的</span></span>
<span class="line"><span>一个卦的义理不是孤立的</span></span>
<span class="line"><span>而是在阴阳流动的网络中体现的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>变卦（一爻之变）：气机的最小单位变化 → 反映变化后的状态</span></span>
<span class="line"><span>复卦（一体之复）：气机的「回归」       → 反映气机的本源</span></span></code></pre></div><p><strong>两者合用</strong>：<strong>变（向前看）+ 复（向后看）= 在时间轴上定位一个卦的义理 = 以见阴阳之气。</strong></p><p><strong>例证的两类</strong>：</p><table tabindex="0"><thead><tr><th>例</th><th>方法</th><th>所得</th></tr></thead><tbody><tr><td>蒙上九 → 师上六</td><td>一爻之变</td><td>蒙的「刚」一失，即成「小人勿用」</td></tr><tr><td>屯初九 → 比初六</td><td>一爻之变</td><td>屯的「以贵下贱」是比「有孚比之」的基础</td></tr><tr><td>大有上体复需、下体复晋</td><td>一体之复</td><td>大有＝饮食宴乐（需）＋昭明之德（晋）</td></tr><tr><td>升上体复姤、下体复复</td><td>一体之复</td><td>升＝一阴升（姤）＋一阳升（复）</td></tr></tbody></table><p><strong>「不唯辞合，义实通明」的两个层次</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>辞合（表层）：文辞上说得通，能解释卦辞爻辞 = 第三章批评的「依文解义」</span></span>
<span class="line"><span>义实通明（深层）：义理真正贯通，知道这个卦在变复网络中的位置 = 第一章说的「知落处」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>全书的最终目标：不是「辞合」，而是「义实通明」</span></span></code></pre></div><p><strong>与第十九章的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第十九章：一卦具八卦（正、伏、互、参）——静态结构：一个卦内含多个卦</span></span>
<span class="line"><span>第二十二章：变复（变卦、复卦）——动态过程：一个卦通过变化连接其他卦</span></span>
<span class="line"><span>合则：静态（内含）+ 动态（变化）= 完整的读卦方法</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把「变」与「复」两个操作分清：<strong>一变一爻，复一体</strong>；</li><li>再读四组例证：<strong>一爻之变的两个，一体之复的两个</strong>；</li><li>记住最后一句：<strong>「苟卦义未审，能以此求之，自然明矣。」</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>须求变复</strong>：卦义不明，用变卦复卦推求。</li><li><strong>一爻之变</strong>：某爻阴变阳或阳变阴。</li><li><strong>一体之复</strong>：上体或下体复归本宫。</li><li><strong>辞合 vs 义实通明</strong>：表层与深层。</li><li><strong>变复成网络</strong>：卦与卦之间互相印证。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(l,{colophon:"须求变复 · 一爻之变 · 一体之复 · 义实通明",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十二章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入。原文所引「蒙上九」「师上六」「屯初九」「比初六」诸条辞句随底本，不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"一爻之变",pinyin:["yī","yáo"],meaning:"某一爻发生变化（阴↔阳）而得变卦。如蒙上九变则成师，屯初九变则成比。"},{term:"一体之复",pinyin:["yī","tǐ"],meaning:"上体或下体复归其本宫之卦。如大有上体复需（饮食之宴）、下体复晋（昭明之德）。"},{term:"辞合",pinyin:["cí","hé"],meaning:"文辞上说得通。这是表层——只做到辞合，仍是第三章批评的「依文解义」。"},{term:"义实通明",pinyin:["yì","shí"],meaning:"义理真正贯通明白。全书方法论的总结句：读卦的终点不是会背卦辞，而是真见其所以然。"},{term:"静与动",pinyin:["jìng","dòng"],meaning:"第十九章「一卦具八卦」是静态（内含多个卦）；第二十二章「变复」是动态（通过变化连接其他卦）。"}]}),a[3]||(a[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>全书方法论的最终总结</strong>，给出读卦的最后一个工具：<strong>变复</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>变＝一爻之变（向前看）  复＝一体之复（向后看）</span></span>
<span class="line"><span>两者合用 = 在时间轴上定位一个卦的义理 = 以见阴阳之气</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「变复」能揭示义理，基于一个假设</strong>：阴阳之气是连续流动的，一个卦的义理不是孤立的，而是在阴阳流动的网络中体现的。</p><p><strong>例证的两类</strong>：</p><table tabindex="0"><thead><tr><th>例</th><th>方法</th><th>所得</th></tr></thead><tbody><tr><td>蒙上九 → 师上六</td><td>一爻之变</td><td>蒙的「刚」一失，即成「小人勿用」</td></tr><tr><td>屯初九 → 比初六</td><td>一爻之变</td><td>屯的「以贵下贱」是比「有孚比之」的基础</td></tr><tr><td>大有复需／晋</td><td>一体之复</td><td>大有＝饮食宴乐（需）＋昭明之德（晋）</td></tr><tr><td>升复姤／复</td><td>一体之复</td><td>升＝一阴升（姤）＋一阳升（复）</td></tr></tbody></table><p><strong>「不唯辞合，义实通明」的两个层次</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>辞合（表层）：文辞上说得通 = 第三章批评的「依文解义」</span></span>
<span class="line"><span>义实通明（深层）：义理真正贯通，知道这个卦在变复网络中的位置 = 第一章说的「知落处」</span></span></code></pre></div><p><strong>与第十九章配成一对</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第十九章：一卦具八卦（正伏互参）——静态结构</span></span>
<span class="line"><span>第二十二章：变复                 ——动态过程</span></span>
<span class="line"><span>合则：静态（内含）+ 动态（变化）= 完整的读卦方法</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>先分清「变」与「复」：<strong>一变一爻，复一体</strong>；</li><li>拿一卦试一次：<strong>把它的某一爻变掉，看变卦的辞是不是和本卦呼应</strong>；</li><li>记住最后一句：<strong>「苟卦义未审，能以此求之，自然明矣。」</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>卦的义理还没有弄清楚时，必须通过变卦和复卦来推求。不只是文辞上符合，义理要真正贯通明白。</p><p>变，是一爻发生变化；复，是整个上体或下体复归。就着变卦和复卦的辞来看，自然的义理无不与本卦吻合——由此可以见到阴阳之气的运行。</p><p>比如蒙卦上九说「击蒙」，变为师卦，师卦上六就说「小人勿用」；屯卦初九说「以贵下贱，大得民也」，变为比卦，比卦初六就说「有孚比之，无咎」——这是一爻之变、辞义相合的例子。</p><p>比如大有卦，上体复归为需卦，有饮食宴乐之象；下体复归为晋卦，有昭明之德。</p><p>升卦的上体复归为姤卦，姤是一阴上升；下体复归为复卦，复是一阳上升——这是一体之复、义理相合的例子。</p><p>如果卦义还没有弄清楚，能用这个方法来推求，自然就明白了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十二章给了最后一招——<strong>卦看不懂时，就把它变一变、退一退；一变之后，义理自己会说话。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「变」与「复」的方向感</strong>——<strong>变是向前看（动了会怎样），复是向后看（从哪里来）。</strong> 这两个方向一夹，卦的位置就定了。</li><li><strong>「蒙变师」的例子</strong>——蒙上九的「刚」是能「击蒙」的原因；刚一去，就成了「小人勿用」。<strong>同一个位置，阴还是阳，含义完全翻转。</strong> 这就是「一爻之变」的力量。</li><li><strong>「升复姤／复」的例子</strong>——升卦的「上升」，居然是<strong>阴阳两个方向同时升</strong>（姤是一阴升，复是一阳升）。<strong>只看卦辞，读不出这一层。</strong></li><li><strong>「不唯辞合，义实通明」</strong>——这是全书方法论的总结句，分量极重。<strong>「辞合」是会背会讲；「义实通明」是真见其所以然。</strong> 麻衣把这两个词并列，就是要人不要把「讲得通」当成「看懂了」。</li><li><strong>与第十九章的配对</strong>——第十九章是<strong>静态的</strong>（一个卦里装着八个卦），本章是<strong>动态的</strong>（一个卦通过变化连着别的卦）。<strong>静＋动，才是完整的读卦法。</strong></li><li><strong>留给自己的问题</strong>：<strong>「义实通明」的「实」，与第二十一章「无有定实」的「实」，是同一个字吗？</strong> 我的看法：<strong>不是。</strong> 第二十一章的「实」是<strong>本体论</strong>的（有没有独立实体），本章的「实」是<strong>认识论</strong>的（是否真见）。<strong>万物假合，故无有定实；而你能在假合中看见那一气，就是义实通明。</strong> 麻衣说完「阴阳一气，但有虚幻」，紧接着就讲「变复通明」——<strong>不是要你在假合世界里找出实体，而是要在假合之中看清那一气。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「落处」（「义实通明」即其终极形态）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-03">第三章 · 卦象视人</a> — 「依文解义」（「辞合」之弊）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-19">第十九章 · 凡具八卦</a> — 静态结构（本章是动态过程）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-21">第二十一章 · 乾坤杂气</a> — 「无有定实」（本章「义实」的对照）</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 卦序的义理相因（本章的变复是另一种关联方式）</li></ul>`,27))])}}});export{m as __pageData,x as default};
